  "concepts": {
    "given": [
      {
        "concept": "number ready",
        "means": "A number is entered before the action.",
        "terms": []
      }
    ],
    "when": [
      {
        "concept": "halve",
        "means": "Halve the entered number, applied either once or twice: applied once it yields half the entered number; applied twice, each application halving the result of the previous one, it yields a quarter of the entered number. Three or more applications are not admitted.",
        "terms": []
      }
    ],
    "then": [
      {
        "concept": "number result",
        "means": "Compare the displayed number with an expected value.",
        "terms": []
      }
    ]
  },
  "glossary": [],
  "description": {
    "summary": "The calculator supports exactly one or two Halve presses per request: one displays half the entered number; two displays its quarter. Three or more presses are not supported."
  }
}
